from typing import Optional

from ...base.client import BaseClient


class ProfileMethods(BaseClient):
    """
    Методы группы 'Профиль' из https://im-docs.corp.mail.ru/
    """

    async def rapi_profile_update(
        self,
        first_name: str,
        last_name: str,
        middle_name: Optional[str] = None,
        about: Optional[str] = None,
    ):
        """
        Изменить информацию о профиле

        Дает возможность поменять поля профиля пользователя,
        список разрешенных для изменения полей задается на сервере.
        :param  firstName: Новое имя
        :param  lastName: Новая фамилия
        :param  middleName: Новое отчество
        :param  about: Новая информация о себе
        """
        return await self.post(
            "rapi/profile/update",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "firstName": first_name,
                    "lastName": last_name,
                    "middleName": middle_name,
                    "about": about,
                },
            },
        )
